RUBRIC:{"title":"AERO9500 Report Marking Rubric (Assignment Part 2)","total":null,"criteria":[{"id":"C1","name":"Introduction: mission concept and rationale","weight":10,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Addresses all required info (primary mission, need, number of spacecraft and why, users/operators/customers) to high standard with detailed descriptions and appropriate literature references."},{"label":"Adequate","min":4,"max":6,"desc":"Addresses some requirements. Descriptions lack specific details and/or referencing is incomplete."},{"label":"Deficient","min":0,"max":3,"desc":"Many or all requirements not addressed. Poor descriptions and lack of appropriate referencing."}]},{"id":"C2","name":"Main body: mission design","weight":60,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Demonstrates high-level understanding of design procedure, clearly addresses mission and course concepts. All major requirements (launch site/vehicle and rationale, orbit type/characteristics/elements, maneuvers, ground facilities, communication frequency, mission duration and EOL plan) well supported with quality evidence (screenshots, software files, hand calculations, literature). Comprehensive, accurate, persuasive."},{"label":"Adequate","min":4,"max":6,"desc":"Demonstrates adequate understanding but design may be inconsistent, unclear, or contain errors. Major requirements addressed but lacking detail or evidence. Content not fully comprehensive or persuasive."},{"label":"Deficient","min":0,"max":3,"desc":"Demonstrates minimal understanding. Major requirements not addressed and/or lack evidence. Content incomplete and not persuasive."}]},{"id":"C3","name":"Conclusion","weight":10,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Detailed and appropriate conclusions drawn from report evidence."},{"label":"Adequate","min":4,"max":6,"desc":"Some conclusions reached but generic or lacking specific detail."},{"label":"Deficient","min":0,"max":3,"desc":"No actual or useful conclusions reached."}]},{"id":"C4","name":"Report presentation","weight":20,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Clear logical engineering report structure, easy to read, good writing/spelling/grammar/style, consistent formatting, concise executive summary/abstract, appropriate clear consistent figures/tables, references in text match list and properly cited."},{"label":"Adequate","min":4,"max":6,"desc":"Not professional level but uses headings/subheadings. Readable but flawed writing/spelling/grammar/style. Figures/tables labelled but formatting unclear/inconsistent affecting context. References mostly correct and match list."},{"label":"Deficient","min":0,"max":3,"desc":"Poorly structured, incoherent, lacks understanding of section purpose. Difficult to read, poor writing with many spelling/grammar errors and inappropriate style. Presentation impedes reading due to inconsistent formatting and unlabelled figures/tables. References not cited or inconsistent."}]}],"notes":"Assignment Part 2 accounts for 25% of course grade."}
TASK:{"title":"AERO9500 Final Report (Part 2) - T3 2020 Assignment","overview":"Design a space mission benefiting Australia and identify main elements of its space segment, demonstrating understanding of launch, orbits and space systems via preliminary mission plan using software (STK, PIGI, or other) supplemented by hand calculations.","deliverables":["Technical report as single PDF including appendix","Relevant screenshots and all STK or PIGI design files (in appendix or included with report)"],"format":{"length":"20 pages max for core part, excluding title page, table of contents, references, appendix","structure":"Executive summary; Introduction - mission overview and rationale; Main body - all sections describing mission's space segment e.g. launch, orbit, ground stations, coverage, mission operation and end-of-life; Conclusion; Bibliography; Appendix (screenshots, STK/PIGI files)","other":"Clear, effective engineering report writing style with correct grammar and spelling; Figures and tables fully and correctly labelled with number, title and reference if necessary; All non-original text/diagrams/ideas cited and referenced, Wikipedia not allowed as proper source"},"requirements":[{"id":"R1","text":"Define spacecraft's primary mission, must benefit Australia, keep concept simple (examples: bushfire tracking and alert, weather satellite, internet/communication, earth observation for city planning/real estate)"},{"id":"R2","text":"State whether mission uses one or multiple spacecraft"},{"id":"R3","text":"Identify users (operator and customers)"},{"id":"R4","text":"Specify launch location and launch vehicle"},{"id":"R5","text":"Specify orbit type, its characteristics and orbital elements"},{"id":"R6","text":"Determine if any orbital maneuvers are required"},{"id":"R7","text":"Identify which ground control facilities will be used and how often spacecraft can communicate with ground control"},{"id":"R8","text":"Define mission duration and plans for end-of-life (EOL)"},{"id":"R9","text":"Use software of choice for design (STK, PIGI requiring competition registration for license, or other with instructor approval) supplemented with hand calculations"},{"id":"R10","text":"Cover in main body space segment elements: launch, orbit, ground stations, coverage, mission operation and end-of-life"}]}
